import { AnimatePresence, LayoutGroup, motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useId, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    badge: "How it fits together",
    headline: "One library,",
    headlineAccent: "every layer.",
    items: [
        {
            label: "Primitives",
            title: "Interaction primitives that feel alive",
