            title: "Surfaces built for AI agents",
            description: "Chat composers, streaming responses, thinking states, and tool-call surfaces designed for modern agent apps.",
            bullets: ["Streaming responses", "Tool-call cards", "Attachments"],
        },
        {
            label: "Blocks",
            title: "Full sections, ready to drop in",
            description: "Pricing, hero, footer, and CTA blocks composed from primitives so you ship complete pages, not fragments.",
            bullets: ["Pricing & CTA", "Hero sections", "Footers"],
        },
        {
            label: "Tooling",
            title: "Install straight from the CLI",
            description: "A private shadcn registry lets you add premium components with one command and keep the source in your repo.",
            bullets: ["shadcn CLI", "Private namespace", "Own the source"],
        },
    ],
} satisfies ArtemisFeatureContent;
const ADVANCE_MS = 4000;
const VIEWPORT = { once: true } as const;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "40%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const WORD_STAGGER = 0.09;
const GRID_SWAP: Transition = { duration: 0.25, ease: ARTEMIS_EASE_OUT };
const COPY_ENTER: Transition = { duration: 0.4, ease: ARTEMIS_EASE_OUT };
const VISUAL_ENTER: Transition = { duration: 0.5, delay: 0.05, ease: ARTEMIS_EASE_OUT };
const INSTANT: Transition = { duration: 0 };
type IconProps = {
    className?: string;
};
function MousePointerClickIcon({ className }: IconProps) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-mouse-pointer-click ${className}`} aria-hidden="true">
      <path d="M14 4.1 12 6"/>
      <path d="m5.1 8-2.9-.8"/>
      <path d="m6 12-1.9 2"/>
      <path d="M7.2 2.2 8 5.1"/>
      <path d="M9.037 9.69a.498.498 0 0 1 .653-.653l11 4.5a.5.5 0 0 1-.074.949l-4.349 1.041a1 1 0 0 0-.74.739l-1.04 4.35a.5.5 0 0 1-.95.074z"/>
    </svg>);
}
function BotIcon({ className }: IconProps) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-bot ${className}`} aria-hidden="true">
      <path d="M12 8V4H8"/>
      <rect width="16" height="12" x="4" y="8" rx="2"/>
      <path d="M2 14h2"/>
      <path d="M20 14h2"/>
      <path d="M15 13v2"/>
      <path d="M9 13v2"/>
    </svg>);
}
function WorkflowIcon({ className }: IconProps) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-workflow ${className}`} aria-hidden="true">
      <rect width="8" height="8" x="3" y="3" rx="2"/>
      <path d="M7 11v4a2 2 0 0 0 2 2h4"/>
      <rect width="8" height="8" x="13" y="13" rx="2"/>
    </svg>);
}
function WrenchIcon({ className }: IconProps) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-wrench ${className}`} aria-hidden="true">
      <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.106-3.105c.32-.322.863-.22.983.218a6 6 0 0 1-8.259 7.057l-7.91 7.91a1 1 0 0 1-2.999-3l7.91-7.91a6 6 0 0 1 7.057-8.259c.438.12.54.662.219.984z"/>
    </svg>);
}
function CheckIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3" aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
const LANDING = "/assets/artemis/448ba79d0d22bebbba13.webp";
const WORKBENCH = "/assets/artemis/448ba79d0d22bebbba13.webp";
/** Each slot's own icon and picture, for tabs that come without one. */
const ICONS = [MousePointerClickIcon, BotIcon, WorkflowIcon, WrenchIcon];
const IMAGES = [LANDING, WORKBENCH, LANDING, WORKBENCH];
const TAB_BASE = "art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent";
const TAB_TAIL = "art:relative art:flex art:shrink-0 art:items-center art:gap-3 art:px-3.5 art:py-2.5 art:text-left art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring art:@min-[1024px]/artemis:w-full";
function wordTransition(index: number): Transition {
    const delay = index * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 140, damping: 26, mass: 1.2, delay },
    };
}
function useReducedAfterMount(): boolean {
    const prefers = useReducedMotion() ?? false;
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    return mounted && prefers;
}
function Word({ index, children }: {
    index: number;
    children: ReactNode;
}) {
    // Read on the first render, so the entrance is already instant with reduced motion; the start still matches the server.
    const reduce = useReducedMotion() === true;
    return (<motion.span className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} whileInView={WORD_SHOWN} viewport={VIEWPORT} transition={reduce ? INSTANT : wordTransition(index)}>
      {children}
    </motion.span>);
}
export default function FeatureSectionsTabs({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const lines = [copy.headline, accent].flatMap((text) => (text ? [text.split(/\s+/).filter(Boolean)] : []));
    const items: ArtemisFeatureItem[] = copy.items;
    const count = items.length;
    const reduce = useReducedAfterMount();
    const groupId = useId();
    const [active, setActive] = useState(0);
    const [hovered, setHovered] = useState<number | null>(null);
    const paused = hovered !== null;
    useEffect(() => {
        if (reduce || paused || count < 2)
            return;
        const id = setTimeout(() => setActive((i) => (i + 1) % count), ADVANCE_MS);
        return () => clearTimeout(id);
    }, [active, paused, reduce, count]);
    const shown = active < count ? active : 0;
    const tab = items[shown];
    const TabIcon = tab?.icon ?? ICONS[shown % ICONS.length];
    const image = tab?.image ?? { src: IMAGES[shown % IMAGES.length], alt: tab?.title ?? "" };
    let wordIndex = 0;
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:max-w-2xl">
              {copy.badge ? (<p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
                {copy.badge}
              </p>) : null}
              <h2 className="art:block art:mt-5 art:text-balance art:text-foreground art:tracking-tight art:text-4xl art:font-medium">
                {lines.map((line, li) => (<span key={li} className="art:block">
                    {line.map((word, wi) => {
                const index = wordIndex++;
                return (<Word key={wi} index={index}>
                          {word}
                          {wi < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
                        </Word>);
            })}
                  </span>))}
              </h2>
            </div>
            <div className="art:mt-12 art:grid art:gap-6 art:@min-[1024px]/artemis:grid-cols-[17rem_1fr]">
              <LayoutGroup id={groupId}>
                <div className="art:flex art:gap-2 art:overflow-x-auto art:pb-1 art:@min-[1024px]/artemis:flex-col art:@min-[1024px]/artemis:overflow-visible art:@min-[1024px]/artemis:pb-0" role="tablist" aria-orientation="vertical">
                  {items.map((t, i) => {
            const on = i === active;
            const Icon = t.icon ?? ICONS[i % ICONS.length];
            const label = t.label ?? t.title;
            return (<motion.button key={label} type="button" className={on
                    ? `${TAB_BASE} art:hover:text-inherit ${TAB_TAIL} art:text-foreground art:rounded-full`
                    : `${TAB_BASE} ${TAB_TAIL} art:text-muted-foreground art:hover:text-foreground art:rounded-full`} role="tab" aria-selected={on} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onMouseEnter={() => setHovered(i)} onMouseLeave={() => setHovered((h) => (h === i ? null : h))} onClick={() => setActive(i)}>
                        {on ? (<motion.span layoutId="feature-tabs-active" className="art:absolute art:inset-0 art:rounded-2xl art:border art:border-border/60 art:bg-background" transition={reduce ? INSTANT : ARTEMIS_SPRING_PANEL}/>) : hovered === i ? (<motion.span className="art:absolute art:inset-0 art:rounded-2xl art:bg-muted/60" initial={false} animate={{ opacity: 1 }}/>) : null}
                        <span className={`art:relative art:grid art:size-9 art:shrink-0 art:place-items-center art:bg-muted art:transition-colors art:rounded-full ${on ? "art:text-foreground" : "art:text-muted-foreground"}`}>
                          <Icon className="art:size-4"/>
                        </span>
                        <span className="art:relative art:font-medium art:text-sm">
                          {label}
                        </span>
                      </motion.button>);
        })}
                </div>
              </LayoutGroup>
              <div className="art:relative art:min-h-[26rem] art:overflow-hidden art:rounded-3xl art:border art:border-border/60">
                <AnimatePresence mode="wait" initial={false}>
                  {tab ? (<motion.div key={active} className="art:grid art:h-full art:@min-[768px]/artemis:grid-cols-2" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={reduce ? INSTANT : GRID_SWAP}>
                    <motion.div className="art:relative art:flex art:flex-col art:justify-center art:p-7 art:@min-[640px]/artemis:p-9" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? INSTANT : COPY_ENTER}>
                      <span className="art:grid art:size-12 art:place-items-center art:bg-muted art:text-foreground art:rounded-full">
                        <TabIcon className="art:size-6"/>
                      </span>
                      <h3 className="art:mt-5 art:font-medium art:text-foreground art:text-xl">
                        {tab.title}
                      </h3>
                      <p className="art:mt-3 art:text-muted-foreground art:text-sm art:leading-7">
                        {tab.description}
                      </p>
                      {tab.bullets?.length ? (<ul className="art:mt-6 art:flex art:flex-col art:gap-2.5">
                        {tab.bullets.map((item) => (<li key={item} className="art:flex art:items-center art:gap-2.5 art:text-foreground art:text-sm">
                            <span className="art:grid art:size-4 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                              <CheckIcon />
                            </span>
                            {item}
                          </li>))}
                      </ul>) : null}
                    </motion.div>
                    <motion.div className="art:relative art:hidden art:overflow-hidden art:@min-[768px]/artemis:block" initial={{ opacity: 0, y: 24, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={reduce ? INSTANT : VISUAL_ENTER}>
                      <div className="art:absolute art:top-9 art:right-0 art:bottom-0 art:left-9 art:translate-x-8">
                        <div className="art:h-full art:overflow-hidden art:rounded-tl-2xl art:border art:border-border/60 art:border-r-0 art:border-b-0 art:bg-background">
                          <div className="art:flex art:items-center art:gap-1.5 art:border-border/60 art:border-b art:bg-muted/40 art:px-3.5 art:py-2.5">
                            <span className="art:size-2.5 art:rounded-full art:bg-muted-foreground/25"/>
                            <span className="art:size-2.5 art:rounded-full art:bg-muted-foreground/25"/>
                            <span className="art:size-2.5 art:rounded-full art:bg-muted-foreground/25"/>
                          </div>
                          <img alt={image.alt} className="art:size-full art:object-cover art:object-left-top" src={image.src}/>
                        </div>
                      </div>
                    </motion.div>
                  </motion.div>) : null}
                </AnimatePresence>
              </div>
            </div>
          </div>
        </section>
      </div>
    </>);
}
